(()=>{
const {createTimeline}=anime;
const display=document.getElementById('glove-display');
const image='<image href="astra-red-glove.png" x="0" y="0" width="1200" height="1400" preserveAspectRatio="xMidYMid meet"/>';
display.innerHTML=`<svg viewBox="0 0 1200 1400" role="img" aria-label="A realistic red leather ASTRA boxing glove, assembled layer by layer on scroll"><defs><clipPath id="knuckles"><path d="M0 0H870L850 190 790 270 720 385 635 490 550 585 430 660 260 700 0 720Z"/></clipPath><clipPath id="thumb"><path d="M870 0H1200V1000L990 1000 925 880 855 720 795 560 720 385 790 270 850 190Z"/></clipPath><clipPath id="palm"><path d="M0 720L260 700 430 660 550 585 635 490 720 385 795 560 855 720 925 880 990 1000 470 1120 0 940Z"/></clipPath><clipPath id="wrist"><path d="M0 940L470 1120 990 1000H1200V1400H0Z"/></clipPath><clipPath id="strap"><path d="M390 1050L1010 860 1130 1210 520 1380Z"/></clipPath><filter id="core-tone"><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncR type="linear" slope=".6"/><feFuncG type="linear" slope=".5"/><feFuncB type="linear" slope=".5"/></feComponentTransfer></filter></defs><g class="assembly-guide"><ellipse cx="600" cy="680" rx="480" ry="570"/><path d="M600 10V1390M40 680H1160"/></g><g class="glove-object"><g class="layer foundation" clip-path="url(#knuckles)" filter="url(#core-tone)">${image}</g><g class="layer shell"><g clip-path="url(#knuckles)">${image}</g></g><g class="layer palm"><g clip-path="url(#palm)">${image}</g></g><g class="layer thumb"><g clip-path="url(#thumb)">${image}</g></g><g class="layer cuff"><g clip-path="url(#wrist)">${image}</g></g><g class="layer strap"><g clip-path="url(#strap)">${image}</g></g><g class="layer finish">${image}</g></g></svg>`;
const tl=createTimeline({autoplay:false});
tl.add('.foundation',{opacity:[.65,1],x:[-70,0],y:[40,0],rotate:[-8,0],duration:700,ease:'outExpo'},0)
.add('.shell',{opacity:[0,1],x:[-300,0],y:[-180,0],rotate:[-16,0],duration:1000,ease:'inOutCubic'},600)
.add('.palm',{opacity:[0,1],x:[-230,0],y:[230,0],rotate:[12,0],duration:900,ease:'inOutCubic'},1600)
.add('.thumb',{opacity:[0,1],x:[300,0],y:[-80,0],rotate:[20,0],duration:900,ease:'inOutCubic'},2500)
.add('.cuff',{opacity:[0,1],y:[300,0],rotate:[-7,0],duration:900,ease:'inOutCubic'},3400)
.add('.strap',{opacity:[0,1],x:[-250,0],rotate:[-12,0],duration:900,ease:'inOutCubic'},4200)
.add('.finish',{opacity:[0,1],duration:500},5100)
.add('.glove-object',{rotate:[-8,5],scale:[.92,1],x:[0,-25],y:[0,-30],duration:1400,ease:'inOutCubic'},5500)
.add('.assembly-guide',{opacity:[.2,0],duration:700},5200);
const section=document.querySelector('.glove-story'),titles=['THE FOUNDATION','THE RED SHELL','THE PALM','THE THUMB','THE WRIST','READY FOR THE ROUND'],copy=['The padded core begins to take shape.','Grained red leather wraps the knuckle form.','The curved palm meets the padded striking surface.','The attached thumb joins the glove.','The cuff and broad wrist strap complete the construction.','One complete form. Leather, padding, and precision.'];let target=0,current=0,lastStage=-1;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function update(){const r=section.getBoundingClientRect();target=Math.max(0,Math.min(1,-r.top/(section.offsetHeight-innerHeight)));}
function frame(){requestAnimationFrame(frame);current+=(target-current)*.09;if(Math.abs(target-current)<.0001)current=target;const p=reduced||document.body.classList.contains('still')?1:current;tl.seek(p*6900);const ms=p*6900;[["shell",600,1000],["palm",1600,900],["thumb",2500,900],["cuff",3400,900],["strap",4200,900],["finish",5100,500]].forEach(([name,start,duration])=>{document.querySelector(".layer."+name).style.opacity=Math.max(0,Math.min(1,(ms-start)/duration))});document.querySelector(".foundation").style.opacity=(.65+Math.min(1,ms/700)*.35)*(1-Math.max(0,Math.min(1,(ms-1000)/600)));const stage=Math.min(5,Math.floor(p*6));if(stage!==lastStage){document.querySelector('#layer-num').textContent=String(stage+1).padStart(2,'0')+' / 06';document.querySelector('#layer-title').textContent=titles[stage];document.querySelector('#layer-copy').textContent=copy[stage];lastStage=stage}document.querySelector('.assembly-track i').style.width=current*100+'%';document.querySelector('#assembly-percent').textContent=Math.round(current*100)+'%';document.querySelector('.assembly-copy').style.opacity=1-Math.min(1,Math.max(0,(current-.06)*5));}
window.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update);update();frame();
})();
